<?php View::component('page-header',['eyebrow'=>'Administração · Demonstração','heading'=>'Perfis e permissões','description'=>'Matriz visual de acessos por perfil. Nenhuma permissão real será alterada.','actionLabel'=>'Salvar permissões','actionHref'=>'#']); ?>
<section class="surface"><div class="surface__header"><div><h2>Perfil selecionado: Administrador</h2><p>Marque ou desmarque permissões para simular a configuração.</p></div><select aria-label="Selecionar perfil"><option>Administrador</option><option>Gestor esportivo</option><option>Treinador</option><option>Consulta</option></select></div><form data-demo-form data-demo-message="Permissões simuladas com sucesso no ambiente de demonstração."><div class="data-table permission-matrix"><table><thead><tr><th scope="col">Módulo</th><?php foreach(['Visualizar','Cadastrar','Editar','Excluir','Exportar'] as $permission): ?><th scope="col"><?= View::e($permission) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach(['Atletas','Documentos','Equipes','Eventos','Benefícios','Relatórios','Usuários'] as $row=>$module): ?><tr><th scope="row"><?= View::e($module) ?></th><?php foreach(range(1,5) as $column): ?><td><input type="checkbox" <?= ($row+$column)%4!==0?'checked':'' ?> aria-label="<?= View::e($module) ?>: permissão <?= $column ?>"></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><footer class="form-actions"><button class="button" type="submit">Salvar simulação</button></footer></form></section>
